import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PermuteAll {
    public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold all permutations
        List<List<Integer>> result = new ArrayList<>();
        // Recursively generate permutations
        permuteRecursive(nums, new ArrayList<>(), result);
        return result;
    }

    private void permuteRecursive(int[] nums, List<Integer> currentPerm, List<List<Integer>> result) {
        // If all elements are permuted, add to result
        if (currentPerm.size() == nums.length) {
            result.add(new ArrayList<>(currentPerm));
            return;
        }
        for (int num : nums) {
            // Skip if the element is already in the current permutation
            if (currentPerm.contains(num)) continue;
            // Add the current element to the current permutation
            currentPerm.add(num);
            // Recursively generate permutations with the added element
            permuteRecursive(nums, currentPerm, result);
            // Remove the element from the current permutation back to backtrack
            currentPerm.remove(currentPerm.size() - 1);
        }
    }

    public static void main(String[] args) {
        List<List<Integer>> permutations = new PermuteAll().permute(new int[]{1, 2, 3});
        System.out.println("The result is: " + permutations);
    }
}
