    public static int findLargestSubstringTitle(List<String> strings) {
        int maxLength = 0;

        // Iterate through each string in the list
        for (String str : strings) {
            // Check if the string or its reverse is a substring of any other string in the list
            for (int i = 0; i < strings.size(); i++) {
                String otherStr = strings.get(i);
                if (otherStr.contains(str) || otherStr.contains(new StringBuilder(str).reverse().toString())) {
                    maxLength = Math.max(maxLength, str.length());
                }
            }
        }

