public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    List<String> uniqueStrings = new ArrayList<>(strings);
    uniqueStrings.sort(Comparator.naturalOrder());
    int[] partials = new int[uniqueStrings.size()];

    int maxLength = 0;

    for (int i = 0; i < uniqueStrings.size(); i++) {
        setPartials(uniqueStrings, i, partials);
        maxLength = Math.max(maxLength, findLongestPalindrome(uniqueStrings, partials, uniqueStrings.get(i), false) + uniqueStrings.get(i).length());
    }

    return maxLength;
}

private void setPartials(List<String> strings, int index, int[] partials) {
    for (int i = index; i < strings.size(); i++) {
        partials[i] = uniqueStrings.get(i).length();
    }
}

private int findLongestPalindrome(List<String> strings, int[] partials, String string, boolean searchInReverse) {
    int left = 0;
    int right = string.length() - 1;
    int maxLength = 0;

    while (left < right) {
        if (string.charAt(left) != string.charAt(right)) {
            break;
        }
        int len = right - left + 1;
        if (len > maxLength) {
            maxLength = len;
        }
        left++;
        right--;
    }

    if (!searchInReverse) {
        return maxLength;
    }

    left = 0;
    right = string.length() - 1;
    maxLength = 0;

    while (left < right) {
        if (string.charAt(left) != string.charAt(right)) {
            break;
        }
        int len = right - left + 1;
        if (len > maxLength) {
            maxLength = len;
        }
        left++;
        right--;
    }

    return maxLength;
}
