@Transactional
public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (int i = 0; i < strings.size(); i++) {
        String str1 = strings.get(i);
        for (int j = 0; j < strings.size(); j++) {
            String str2 = strings.get(j);
            if (str2 != str1 && check palindrome(str1, str2) || check palindrome(str1, reverse(str2))) {
               maxLength = Math.max(maxLength, Math.min(str1.length(), str2.length()));
            }
        }
    }

    return maxLength;
}

private boolean check palindrome(String str1, String str2) {
    return str1.equals(str2);
}

private String reverse(String str) {
    StringBuilder reversedStr = new StringBuilder();
    for (int i = str.length() - 1; i >= 0; i--) {
        reversedStr.append(str.charAt(i));
    }
    return reversedStr.toString();
}
