public static int countOilDeposits(char[][] grid) {
    int count = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                fillConnectedRegions(grid, i, j, visited);
            }
        }
    }
    return count;
}

private static void fillConnectedRegions(char[][] grid, int row, int col, boolean[][] visited) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != '@' || visited[row][col]) {
        return;
    }
    visited[row][col] = true;
    fillConnectedRegions(grid, row + 1, col, visited); // Down
    fillConnectedRegions(grid, row - 1, col, visited); // Up
    fillConnectedRegions(grid, row, col + 1, visited); // Right
    fillConnectedRegions(grid, row, col - 1, visited); // Left
}
