public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                // Check if the cell is part of an existing oil deposit
                if (isNotPartOfExistingDeposit(grid, i, j)) {
                    count++;
                }
            }
        }
    }

    return count;
}

private static boolean isNotPartOfExistingDeposit(char[][] grid, int i, int j) {
    // Helper method to check if the cell is not visited yet
    for (int k = i - 1; k <= i + 1; k++) {
        for (int l = j - 1; l <= j + 1; l++) {
            if (k >= 0 && k < grid.length && l >= 0 && l < grid[0].length && grid[k][l] == '@') {
                // This cell is visited as part of an existing oil deposit
                return false;
            }
        }
    }
    return true;
}

