public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) {
        throw new IllegalArgumentException("Start and end coordinates cannot be null");
    }
    if (start.length != 2 || end.length != 2 || paths == null || paths.length < n - 1) {
        throw new IllegalArgumentException("Invalid parameters");
    }

    boolean[][] graph = new boolean[n][n];
    Map<Integer, Integer> positionMap = new HashMap<>();

    // Initialize the graph and position map
    for (int i = 0; i < n; i++) {
        positionMap.put(i, i);
    }
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        graph[from][to] = true;
        graph[to][from] = true;
    }

    // Perform Depth-First Search to check if a path exists from start to end
    if (dfs(graph, start[0], end[0], positionMap, new boolean[n])) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private boolean dfs(boolean[][] graph, int current, int target, Map<Integer, Integer> positionMap, boolean[] visited) {
    if (current == target) {
        return true;
    }
    visited[current] = true;

    for (int next : findNeighbours(graph, current, positionMap)) {
        if (!visited[next] && dfs(graph, next, target, positionMap, visited)) {
            return true;
        }
    }

    return false;
}

private int[] findNeighbours(boolean[][] graph, int vertex, Map<Integer, Integer> positionMap) {
    int n = positionMap.size();
    int[] neighbours = new int[n];
    int index = 0;

    for (int i = 0; i < n; i++) {
        if (graph[vertex][i] && positionMap.get(i) != vertex) {
            neighbours[index++] = i;
        }
    }

    return Arrays.copyOf(neighbours, index);
}
