public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        throw new IllegalArgumentException("All parameters must be provided");
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    int[][] directions = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0} // Right, Left, Down, Up
    };

    boolean[][] visited = new boolean[n][n];
    boolean isValidPath = dfs(n, startX, startY, paths, visited, endX, endY);
    if (isValidPath) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(int n, int x, int y, int[][] paths, boolean[][] visited, int endX, int endY) {
    // If already visited or out of bounds, return false
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }

    // If reached the end point, return true
    if (x == endX && y == endY) {
        return true;
    }

    // Mark the current cell as visited
    visited[x][y] = true;

    // Explore all four possible directions
    boolean result = false;
    for (int[] direction : directions) {
        int newX = x + direction[0];
        int newY = y + direction[1];
        if (dfs(n, newX, newY, paths, visited, endX, endY)) {
            result = true;
            break;
        }
    }

    // Backtrack by marking the cell as unvisited
    visited[x][y] = false;

    return result;
}
