import java.util.LinkedList;

public class MazeTraveler {
    /**
     * Determines if travel from the starting n-tersection to the ending n-tersection is possible.
     *
     * @param n    the size of the n-teresting space
     * @param start the starting n-tersection coordinates
     * @param end   the ending n-tersection coordinates
     * @param paths the paths between adjacent n-tersections in the n-teresting space
     * @return "can be travelled" if travel is possible, "cannot be travelled" otherwise
     */
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        LinkedList<int[]> queue = new LinkedList<>();
        queue.add(new int[]{start[0], start[1]});

        // Mark the start point as visited
        visited[start[0]][start[1]] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            // Check if the current position is the end position
            if (current[0] == end[0] && current[1] == end[1]) {
                return "can be travelled";
            }

            // Explore all adjacent locations
            for (int i = 0; i < paths.length; i++) {
                int[] next = paths[i];
                if (isValidPosition(next[0], next[1], n)) {
                    if (!visited[next[0]][next[1]]) {
                        queue.add(next);
                        visited[next[0]][next[1]] = true;
                    }
                }
            }
        }

        // If the queue is empty and the start and end positions are not the same, travel is not possible
        return "cannot be travelled";
    }

    private static boolean isValidPosition(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}
