        if (path[0] == startX && path[1] == startY && (path[2] == endX && path[3] == endY || path[2] == endY && path[3] == startX || path[0] == endX && path[1] == endY)) {
            return "can be travelled";
        }
    }

    return "cannot be travelled";
}
