public static String appx(String word1, String word2) {
    int a = occurrencesOf(word1, word2);
    int b = occurrencesOf(word2, word1);

    if (a == 0 || b == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    } else if (a == b) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    } else {
        int gcd = GCD(a, b);
        int numerator = (a * b) / gcd;
        int denominator = a + b;
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

public static int occurrencesOf(String word1, String word2) {
    int count = 0;
    int minLen = Math.min(word1.length(), word2.length());

    for (int i = 0; i < minLen; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            count++;
        }
    }

    return count;
}

public static int GCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
