public static String appx(String word1, String word2) {
    long commonLetters = 0;
    long word1Length = word1.length();
    long word2Length = word2.length();

    for (int i = 0; i < word1Length; i++) {
        if (word2.contains(String.valueOf(word1.charAt(i)))) {
            commonLetters++;
        }
    }

    if (word1Length == 0 || word2Length == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0/1";
    }

    long numerator = commonLetters;
    long denominator = word1Length + word2Length;

    return "appx(" + word1 + ", " + word2 + ") = " + convertToReducedFraction(numerator, denominator);
}

private static String convertToReducedFraction(long numerator, long denominator) {
    long gcd = calculateGCD(numerator, denominator);
    return numerator / gcd + "/" + denominator / gcd;
}

private static long calculateGCD(long num1, long num2) {
    if (num2 == 0) {
        return num1;
    }
    return calculateGCD(num2, num1 % num2);
}
