import java.util.Arrays;

public class MedianFinder {

    private int[] minHeap = new int[1000];
    private int sizeMinHeap = 0;
    private int[] maxHeap = new int[1000];
    private int sizeMaxHeap = 0;

    public double trimMean(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        inttrimSize = n * 5 / 100;

        double sum = 0;
        int totalValidElements = 0;
        for (int i = trimSize; i < n - trimSize; i++) {
            sum += arr[i];
            totalValidElements++;
        }

        return sum / totalValidElements;
    }

    public void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public int extractMax() {
        if (sizeMaxHeap == 0) {
            return Integer.MIN_VALUE;
        }
        int max = maxHeap[0];
        maxHeap[0] = maxHeap[sizeMaxHeap - 1];
        sizeMaxHeap--;
        minHeapify(0);
        return max;
    }

    public void insertMax(int value) {
        maxHeap[sizeMaxHeap] = value;
        sizeMaxHeap++;
        heapifyUp(sizeMaxHeap - 1);
    }

    private void minHeapify(int index) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int smallest = index;

        if (left < sizeMaxHeap && maxHeap[left] > maxHeap[smallest]) {
            smallest = left;
        }
        if (right < sizeMaxHeap && maxHeap[right] > maxHeap[smallest]) {
            smallest = right;
        }

        if (smallest != index) {
            swap(maxHeap, index, smallest);
            minHeapify(smallest);
        }
    }

    private void heapifyUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (maxHeap[parent] < maxHeap[index]) {
                swap(maxHeap, index, parent);
                index = parent;
            } else {
                break;
            }
        }
    }

    public int extractMin() {
        if (sizeMinHeap == 0) {
            return Integer.MAX_VALUE;
        }
        int min = minHeap[0];
        minHeap[0] = minHeap[sizeMinHeap - 1];
        sizeMinHeap--;
        maxHeapify(0);
        return min;
    }

    public void insertMin(int value) {
        minHeap[sizeMinHeap] = value;
        sizeMinHeap++;
        heapifyUp(sizeMinHeap - 1);
    }

    private void maxHeapify(int index) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int largest = index;

        if (left < sizeMinHeap && minHeap[left] < minHeap[largest]) {
            largest = left;
        }
        if (right < sizeMinHeap && minHeap[right] < minHeap[largest]) {
            largest = right;
        }

        if (largest != index) {
            swap(minHeap, index, largest);
            maxHeapify(largest);
        }
    }

    private void heapifyUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (minHeap[parent] > minHeap[index]) {
                swap(minHeap, index, parent);
                index = parent;
            } else {
                break;
            }
        }
    }
