import java.util.List;
import java.util.HashSet;

public class MinTimeToCollectApples {

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> graph = buildGraph(edges);

        int totalTime = 0;
        HashSet<Integer> visited = new HashSet<>();
        for (int i = 0; i < graph.size(); i++) {
            if (!visited.contains(i)) {
                totalTime += traverse(graph, i, hasApple, visited);
            }
        }

        return totalTime;
    }

    private int traverse(List<List<Integer>> graph, int start, boolean[] hasApple, HashSet<Integer> visited) {
        visited.add(start);

        int totalCost = 0;
        for (int neighbor : graph.get(start)) {
            if (visited.contains(neighbor)) {
                continue;
            }

            totalCost += traverse(graph, neighbor, hasApple, visited);
            if (hasApple[neighbor]) {
                totalCost += 2; // Cost for visiting the neighbor and back to the current node
            }
        }

        return totalCost;
    }

    private List<List<Integer>> buildGraph(int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < edges.length; i++) {
            if (graph.get(edges[i][0]) == null) {
                graph.add(edges[i][0], new ArrayList<>());
            }

            if (graph.get(edges[i][1]) == null) {
                graph.add(edges[i][1], new ArrayList<>());
            }

            graph.get(edges[i][0]).add(edges[i][1]);
            graph.get(edges[i][1]).add(edges[i][0]);
        }

        return graph;
    }

    public static void main(String[] args) {
