        // Helper function to perform DFS and count the time taken to collect apples
        return dfs(0, graph, hasApple, -1, 0);
    }

    private int dfs(int node, List<List<Integer>> graph, boolean[] hasApple, int parent, int time) {
        int timeTaken = 0;
        for (int neighbor : graph.get(node)) {
            if (neighbor != parent) {
                // Call DFS for the neighbor
                timeTaken = dfs(neighbor, graph, hasApple, node, timeTaken);

                // If the neighbor has an apple or its direct parent has an apple, add the time to the total time
                if (hasApple[neighbor] || (parent != -1 && hasApple[parent])) {
                    timeTaken += 2;
                }
            }
        }
        return timeTaken;
    }
