import java.util.Arrays;

public class ArraySplitter {

    public boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length <= 1) {
            return false;
        }

        Arrays.sort(nums);
        int n = nums.length;
        double totalSum = sum(nums);
        double maxPossibleSum = totalSum / 2;

        for (int partitionSize = 1; partitionSize <= n / 2; partitionSize++) {
            double maxSubarraySum = sum(nums, 0, partitionSize - 1);
            if (maxSubarraySum > maxPossibleSum) {
                break;
            }
            double otherSubarraySum = totalSum - maxSubarraySum;
            if (otherSubarraySum % partitionSize == 0) {
                return true;
            }
        }

        return false;
    }

    private static double sum(int[] arr, int start, int end) {
        double sum = 0;
        for (int i = start; i <= end; i++) {
            sum += arr[i];
        }
        return sum;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(splitArraySameAverage(new int[]{1, 2, 3, 4, 5, 6, 7, 8})); // true
        System.out.println(splitArraySameAverage(new int[]{3, 1})); // false
    }
}
