public class Solution {

    public boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length < 2) {
            return false;
        }

        int sum = Arrays.stream(nums).sum();
        int n = nums.length;

        for (int i = 1; i < n; i++) {
            if (sum % i != 0) {
                continue;
            }

            int target = sum / i;
            boolean[](dp = new boolean[target + 1]) {
                dp[0] = true;
            }

            for (int num : nums) {
                for (int j = target; j > 0; j--) {
                    if (dp[j]) {
                        dp[j - num] = true;
                        if (j == num) {
                            dp[j] = false;
                        }
                    }
                }
            }

            if (dp[target]) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(splitArraySameAverage(new int[]{1, 2, 3, 4, 5, 6, 7, 8})); // Output: true
        System.out.println(splitArraySameAverage(new int[]{3, 1})); // Output: false
