import java.util.Arrays;

public class ArrayAverageSplitter {

    /**
     * Checks if it is possible to split the given integer array into two non-empty arrays
     * with the same average.
     *
     * @param nums The array of integers to split.
     * @return true if there is a way to split the array into two equal averages, false otherwise.
     */
    public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int n = nums.length;
        // If the total sum is odd, splitting into equal averages is not possible
        if (totalSum % n != 0) {
            return false;
        }

        double avg = totalSum / n;

        int[] prefixSums = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixSums[i] = prefixSums[i - 1] + nums[i - 1];
        }

        // Check if there exists an index i such that prefixSums[i] * (n - i) == avg * n
        return Arrays.stream(prefixSums).anyMatch(prefixSum -> prefixSum * (n - prefixSum) == avg * n);
    }

    public static void main(String[] args) {
        System.out.println(splitArraySameAverage(new int[]{1,2,3,4,5,6,7,8})); // Output: true
        System.out.println(splitArraySameAverage(new int[]{3,1})); // Output: false
    }
}
