import java.util.*;

class Solution {
    /**
     * Calculates the minimum cost to reach the top of the floor from either step with index 0 or 1.
     *
     * @param cost An array of integers representing the cost of each step on the staircase.
     * @return The minimum cost to reach the top of the floor.
     */
    public int minCostClimbingStairs(int[] cost) {
        if (cost.length <= 2) {
            return Math.min(cost[0], cost[1]);
        }

        int[] dp = new int[cost.length];
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < cost.length; i++) {
            dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
        }

        return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
    }

    public static void main(String[] args) {
        Solution solution = new Solution();

        // Test case 1
        int[] cost1 = {10, 15, 20};
        System.out.println(solution.minCostClimbingStairs(cost1)); // Output: 15

        // Test case 2
        int[] cost2 = {1, 100, 1, 1, 1, 100, 1, 1, 100, 1};
        System.out.println(solution.minCostClimbingStairs(cost2)); // Output: 6
    }
}
