public boolean hasAllCodes(String s, int k) {
    int mask = 0;
    for (int i = 0; i < k; i++) {
        mask <<= 1;
        mask |= 1;
    }
    for (int i = k; i <= s.length() - k; i++) {
        int windowMask = 0;
        for (int j = i; j < i + k; j++) {
            windowMask <<= 1;
            windowMask |= s.charAt(j) == '1' ? 1 : 0;
        }
        if ((mask & windowMask) == 0) {
            return false;
        }
    }
    return true;
}
