class Solution {
    public int minOperations(int n) {
        int start = 1;
        int end = 2 * n - 1;
        int operations = 0;

        while (start < end) {
            operations += (end - start) / 2;
            start = (end - start) / 2 + start;
            end = end - start;
        }

        return operations;
    }
