import java.util.ArrayList;
import java.util.List;

public class FibonacciMinimum {

    public int findMinFibonacciNumbers(int k) {
        List<Integer> fibs = new ArrayList<>();
        int[] memo = new int[k+1];
        tieTofib(k, fibs);
        return sumFib(k, memo, fibs);
    }

    private void tieTofib(int n, List<Integer> fibs) {
        if (n < 2) {
            fibs.add(n);
            return;
        }
        fibTofib(n - 1, fibs);
        fibTofib(n - 2, fibs);
        List<Integer> arr = new ArrayList<>();
        fibs.forEach(integer -> arr.add(integer));
        if (arr.size() != 2) fibs.clear();
        fibs.add(n);
    }

    private int sumFib(int target, int[] memo, List<Integer> fibs) {
        if (target == 0) return 0;
        if (memo[target] != 0) return memo[target];
        if (target > fibs.get(fibs.size()-2)) return (int) ( -(sumFib(target, memo, fibs)) );
        int ans = Integer.MAX_VALUE;
        for(int i = fibs.size()-1;i >= 0;i--) {
            ans = Math.min(sumFib(target-fibs.get(i), memo, fibs) + 1, ans);
        }
        memo[target] = ans;
        return ans;
    }
}
