     *
     * @param k The target sum.
     * @return The minimum number of Fibonacci numbers whose sum is equal to k.
     */
    public static int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        fibNumbers.add(1);
        fibNumbers.add(1);

        while (true) {
            int nextFib = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
            if (nextFib > k) {
                break;
            }
            fibNumbers.add(nextFib);
        }

        int count = 0;
        for (int fib : fibNumbers) {
            while (k >= fib) {
                count++;
                k -= fib;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the target sum: ");
        int k = sc.nextInt();
        sc.close();

        int result = findMinFibonacciNumbers(k);
        System.out.println("The minimum number of Fibonacci numbers whose sum is " + k + " is: " + result);
    }
