public class KthSmallestFactor {
    /**
     * Finds and returns the kth smallest factor of a given number n.
     * If n has fewer than k factors, returns -1.
     *
     * @param n the number to find the factor of
     * @param k the index of the factor to find
     * @return the kth smallest factor of n, or -1 if not enough factors
     */
    public static int kthFactor(int n, int k) {
        Map<Integer, Integer> factorsMap = findFactors(n);
        List<Integer> factors = new ArrayList<>(factorsMap.keySet());
        Collections.sort(factors);

        if (k <= factors.size()) {
            return factors.get(k - 1);
        } else {
            return -1;
        }
    }

    private static Map<Integer, Integer> findFactors(int n) {
        Map<Integer, Integer> factors = new HashMap<>();
        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                factors.put(i, factors.getOrDefault(i, 0) + 1);
                int otherFactor = n / i;
                if (i != otherFactor) {
                    factors.put(otherFactor, factors.getOrDefault(otherFactor, 0) + 1);
                }
            }
        }
        return factors;
    }
}
