private int maxUniqueSplit(String s, int start, int currentCount, HashMap<String, Integer> map) {
    if (start == s.length()) {
        return currentCount;
    }
    int max = Integer.MIN_VALUE;
    for (int i = start; i < s.length(); i++) {
        String slice = s.substring(start, i + 1);
        if (!map.containsKey(slice)) {
            map.put(slice, currentCount);
            max = Math.max(max, maxUniqueSplit(s, i + 1, currentCount + 1, map));
            map.remove(slice);
        }
    }
    return max;
}
