private static int countDigitOneHelper(int n, long powerOfTen) {
    long high = n / (long)(powerOfTen * 10);
    long low = (long)(n % (powerOfTen * 10));
    long cur = n - low - high * powerOfTen;

    int count = high * powerOfTen + (cur >= 1 ? 1 + Math.min(cur, powerOfTen - 1) : (cur > 0 ? 1 : 0));

