public static int countDigitOne(int n) {
    if (n == 0) return 0;

    int count = 0;
    int placeValue = 1;

    while (n >= placeValue) {
        int digitAtPlace = n % 10;
        int digitsBefore = n / (placeValue * 10);
        int digitsAfter = n % (placeValue * 10) - digitAtPlace;

        count += digitsBefore * placeValue;

        if (digitAtPlace == 0) {
            count -= digitsAfter;
        } else if (digitAtPlace == 1) {
            count += digitsAfter + 1;
        } else {
            count += (placeValue - digitAtPlace) * digitsAfter;
        }

        placeValue *= 10;
    }

    return count;
}
