public static int squarePermutations(int[] A) {
    int N = A.length;
    return (int) sqrt(N) * outerLoop(A);
}

static long sqrt(long n) {
    return (int) Math.sqrt(n);
}

static int getNum(int num) {
    if ((num & 1) == 0) return 0;
    return 1;
}

static int innerLoop(int[] A) {
    int N = A.length;
    int[] count = new int[N + 1];

    int i, left, right, mid;

    for (i = 1; i <= N; i++) {
        if (num % i == 0) {
            count[i]++;
            final int r = num / i;
            if (r != i) count[r]++;
        }
    }

    left = right = i = 1;
    do {
        mid = i / 2;

        if (count[left] <= count[mid]) {
            right = mid;
        } else {
            left = mid + 1;
        }
    } while (left < right);

    if (N % 2 != 0) {
        if (left > 0) {
            count[left]++;
        } else {
            count[right]++;
        }
    }

    for (i = Math.min(N / 2, left); i >= 2; i--) {
        if ((i & 1) == 0) count[i] += count[i - 1] / 2;
        else count[i] += (count[i - 1] + 1) / 2;

        A[i] = A[left - i + 1];
    }

    return (bisect(A, right, 0, N - 1, i) & 1) == 0;
}

static boolean bisect(int[] A, int key, int l, int r, int k) {
    int m = l + (r - l) / 2;
    if (r - l == 1) return (A[l] >= k);
    if (l == r) {
        if (key >= A[l]) return true;
        return false;
    }
    if (A[m] == key) {
        return true;
    } else if (A[m] < key) {
        return bisect(A, key, m, r, k);
    } else {
        return bisect(A, key, l, m, k);
    }
}
