public static int squarePermutations(int[] A) {
    boolean[] seen = new boolean[A.length];
    int count = 0;

    for (int i = 0; i < A.length; i++) {
        if (!seen[i]) {
            HashMap<Integer, Integer> squareMap = new HashMap<>();
           Helper(A, i, squareMap, seen, count);
        }
    }

    return count;
}

private static void Helper(int[] A, int index, HashMap<Integer, Integer> squareMap, boolean[] seen, int& total) {
    if (index == A.length) {
        total++;
        return;
    }

    for (int j = 0; j < A.length; j++) {
        if (j == index || !seen[j] || (index > 0 && A[j] == 2 * A[index - 1]) || squareMap.containsKey(A[j]) && !squareMap.get(A[j]).contains(index)) {
            continue;
        }

        squareMap.putIfAbsent(A[j], new HashSet<>());
        squareMap.get(A[j]).add(index);

        seen[j] = true;
        Helper(A, index + 1, squareMap, seen, total);
        seen[j] = false;
    }
}
