import java.util.*;

class Solution {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n % 2 != 0)
            return 0;
        int mid = n / 2;
        int[] fact = new int[n];
        int temp = 1, ans = 1;
        for (int i = 0; i < n; i++)
            fact[i] = temp++;

        Arrays.fill(fact, 1);
        for (int i = 0; i < n; i++)
            fact[i] = fact[i] * (fact[n - i - 1] * fact[i]);

        Arrays.sort(A);

        for (int i = 0; i < n; i++)
            if (i > 0 && A[i] == A[i - 1])
                return 0;

        stack<Integer> s = new Stack<>();
        s.push(A[0]);
        for (int i = 1; i < n; i++) {
            while (!s.isEmpty() && A[i] <= 2 * s.peek()) {
                int top = s.pop();
            }
            s.push(A[i]);
        }

        while (!s.isEmpty()) {
            if (s.size() == n - mid)
                ans = ans * fact[0];
            else
