public static int squarePermutations(int[] A) {
    int len = A.length;
    if (len % 2 != 0) return 0; // If length is odd, no pairing is possible
    int mid = len / 2;
    int k = 0;
    int[] A1 = new int[mid];
    int[] A2 = new int[mid];

    for (int i = 0; i < mid; i++) {
        if (A[i] % 4 == 0 || A[i] == 4) {
            // If A[i] is a square number
            A1[k++] = A[i];
            A2[k++] = A[i];
        }
    }

    for (int i = mid; i < len; i++) {
        if (A[i] % 4 == 0 || A[i] == 4) {
            // If A[i] is a square number, it must be paired with A[i] / 4 to make a perfect square
            if (k < mid) A2[k++] = A[i] / 4;
        }
    }

    int i = 0;
    int j = k - 1;
    int count = 1;
    int sum;

    while (i <= j) {
        sum = A1[i] + A2[j];
        if ((int) Math.sqrt(sum) * (int) Math.sqrt(sum) == sum) {
            count *= combination(k - 1, j - i);
            i++;
            j--;
        } else if (sum < 25) {
            j--;
        } else {
            i++;
        }
    }

    return count;
}

private static int combination(int n, int k) {
    if (k > n - k) k = n - k;
    int c = 1;
    for (int i = 1; i <= k; i++) {
        c = c * (n - i + 1) / i;
    }
    return c;
}
