public class MaxAreaCalculator {
    /**
     * Calculates the largest rectangle area in a series of bars.
     * 
     * @param height An array of integers representing the heights of bars.
     * @return The largest rectangle area.
     */
    public static int largestRectangleArea(int[] height) {
        if (height == null || height.length == 0) {
            return 0;
        }

        int[] nextSmaller = new int[height.length];
        int[] prevSmaller = new int[height.length];
        Arrays.fill(nextSmaller, height.length);
        Arrays.fill(prevSmaller, -1);

        // Find index of closest smaller element to the left of each element
        for (int i = 0; i < height.length; i++) {
            while (prevSmaller[i] >= 0 && height[i] <= height[prevSmaller[i]]) {
                prevSmaller[i] = prevSmaller[prevSmaller[i]];
            }
        }

        // Find index of closest smaller element to the right of each element
        for (int i = height.length - 1; i >= 0; i--) {
            while (nextSmaller[i] < height.length && height[i] <= height[nextSmaller[i]]) {
                nextSmaller[i] = nextSmaller[nextSmaller[i]];
            }
        }

        int maxArea = 0;
        for (int i = 0; i < height.length; i++) {
            int width = nextSmaller[i] - prevSmaller[i] - 1;
            int area = height[i] * width;
            maxArea = Math.max(maxArea, area);
        }

        return maxArea;
    }

    public static void main(String[] args) {
        // Test cases
        int result1 = largestRectangleArea(new int[]{2,1,5,6,2,3});
        System.out.println("The largest rectangle area for input [2,1,5,6,2,3] is: " + result1); // Output: 10

        int result2 = largestRectangleArea(new int[]{2,4});
        System.out.println("The largest rectangle area for input [2,4] is: " + result2); // Output: 4
    }
