import java.util.HashSet;
import java.util.Set;

public class SmallestIntegerFinder {
    /**
     * Finds the smallest integer greater than the input n by rearranging its digits.
     *
     * @param n The input positive integer.
     * @return The smallest integer greater than n, or -1 if not possible.
     */
    public static int findSmallestInteger(int n) {
        Set<Integer> usedDigits = new HashSet<>();
        int originalInt = n;
        boolean hasNext = false;

        while (true) {
            for (int i = 0; i < 10; i++) {
                if (i != originalInt % 10 && !usedDigits.contains(i)) {
                    if (isdigitGreater(originalInt, i)) {
                        int newInt = originalInt * 10 + i;
                        usedDigits.add(i);
                        if (newInt > originalInt) {
                            hasNext = true;
                            return newInt;
                        }
                    }
                }
            }
            if (!hasNext) {
                return -1;
            }
        }
    }

    private static boolean isdigitGreater(int originalInt, int digit) {
        int carry = 0;

        while (originalInt > 0) {
            int d = originalInt % 10;
            if (d > digit + carry) {
                carry = d - digit - 1;
                return true;
            } else if (d == digit + carry) {
                carry = 0;
            }
            originalInt /= 10;
        }

        return carry > 0;
    }
}
