public class SmallestIntegerFinder {

    public static int findSmallestInteger(int n) {
        BigInteger BigIntegerN = BigInteger.valueOf(n);
        BigInteger min = BigInteger.ONE;

        // Convert to string to find the highest digit
        String strN = BigIntegerN.toString();
        char max_digit = strN.charAt(strN.length() - 1);

        // Try to find the smallest integer
        while (true) {
            String next_number = nextPermutation(strN);
            if (next_number == null || nextNumber.replaceAll("0", "").length() > 0) {
                // This is still trying to find the smallest integer
                // And we are out of options because current digit is the highest
                break;
            }
            BigInteger num = new BigInteger(next_number);
            if (next_number.length() < strN.length() && num.compareTo(min) < 0) {
                min = num;
            }
        }

        return min.intValue();
    }

    /**
     * Gets the next permutation of the given string.
     *
     * @param s The string to find the next permutation for.
     * @return The next permutation string, or null if there are no
     *         more permutations.
     */
    private static String nextPermutation(String s) {
        char[] sArray = s.toCharArray();
        int i = sArray.length - 2;

        // Find the first character from the right that is smaller than
        // the character next to it.
        while (i >= 0 && sArray[i] >= sArray[i + 1]) {
            i--;
        }

        // If no such character is found, then the string is in highest
        if (i == -1) {
            return null; // No more permutations possible
        }

        // Find the smallest character to the right of i that is
        // greater than sArray[i].
        int j = sArray.length - 1;
        while (sArray[j] <= sArray[i]) {
            j--;
        }

        // Swap sArray[i] and sArray[j]
        char temp = sArray[i];
        sArray[i] = sArray[j];
        sArray[j] = temp;

        // Reverse the substring from i+1 to the end
        Arrays.sort(sArray, i + 1, sArray.length);
        return new String(sArray);
    }

    public static void main(String[] args) {
        System.out.println(findSmallestInteger(12)); // Output: 21
        System.out.println(findSmallestInteger(4321)); // Output: 1234
        System.out.println(findSmallestInteger(5)); // Output: -1
    }
}
