public class Solution {
    public static boolean isBoomerang(int[][] points) {
        if (points.length != 3) {
            throw new IllegalArgumentException("There must be exactly 3 points.");
        }

        Point p1 = new Point(points[0][0], points[0][1]);
        Point p2 = new Point(points[1][0], points[1][1]);
        Point p3 = new Point(points[2][0], points[2][1]);

        int determinant = p1.x * (p2.y - p3.y) + p2.x * (p3.y - p1.y) + p3.x * (p1.y - p2.y);

        return determinant != 0;
    }
}
