private static int[] primeFactors = {2, 3, 5};

public static int findNthUglyNumber(int target) {
    int index = 1, uglyNumber = 1; // Starting from the first ugly number (1)
    Set<Integer> seen = new HashSet<>();
    seen.add(uglyNumber);

    while (index < target) {
        long nextUglyNumber = getNextUglyNumber(uglyNumber);
        if (!seen.contains((int) nextUglyNumber)) {
            uglyNumber = (int) nextUglyNumber;
            seen.add(uglyNumber);
            index++;
        }
    }

    return uglyNumber;
}

private static long getNextUglyNumber(long currentUglyNumber) {
    long minVal = Long.MAX_VALUE;
    for (int prime : primeFactors) {
        long nextMultiplication = currentUglyNumber * prime;
        if (nextMultiplication < minVal) {
            minVal = nextMultiplication;
        }
    }
    return minVal;
}
