public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    PriorityQueue<Integer> pq = new PriorityQueue<>(n);
    pq.offer(1);
    Set<Integer> visited = new HashSet<>();
    visited.add(1);

    for (int a = 1; a <= n; a++) {
        int cur = pq.poll();
        for (int multi : new int[]{2, 3, 5}) {
            int next = cur * multi;
            if (visited.add(next)) {
                pq.offer(next);
            }
        }
    }
    return pq.poll();
}
