public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    ans(1, 0, n, result);
    return result;
}

private static void ans(int n, int level, int end, List<Integer> result) {
    if (level > end) {
        return;
    }

    for (int i = 0; i <= 9; i++) {
        if ((i == 0 && level > 0) || (level == 0 && i == 1 && n < 10)) {
            continue;
        }
        int curr = n * 10 + i;
        if (curr <= end) {
            result.add(curr);
            if (curr < end) {
                ans(curr, level + 1, end, result);
            }
        }
    }
}
