public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    recur(new AtomicInteger(), 1, n, result);
    return result;
}

private static void recur(AtomicInteger i, int start, int end, List<Integer> result) {
    if (start > end) {
        return;
    }
    result.add(start);
    i.set(start);
    for (int j = 0; i.get() * 10 + j <= end; j++) {
        recur(i, i.get() * 10 + j, end, result);
    }
}
